CID = 'numpy3'
LOOP, SPLIT, SEARCH, RAND, DIST, UFUNC = "Looping over arrays", "Splitting arrays", "Searching arrays", "Random numbers", "Random data distributions", "ufuncs: NumPy's fast maths functions"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
NP = 'import numpy as np\n'
Q = [
 # ---------- Basic ----------
 T(1, LOOP, NP + 'm = np.array([[1, 2], [3, 4]])\nfor row in m:\n    print(row.sum())', "Looping over a 2D array gives one row at a time, and each row is itself an array."),
 W(1, SPLIT, 'Split `np.arange(1, 10)` into 3 equal parts with `np.split`, and print each part on its own line.', NP, NP + 'for part in np.split(np.arange(1, 10), 3):\n    print(part)', "`np.split(a, 3)` cuts the array into 3 equal pieces. 9 values make 3 pieces of 3."),
 W(1, SEARCH, '`a = np.array([4, 7, 4, 9, 4])`. Print the positions of every 4, using `np.where`.', NP + 'a = np.array([4, 7, 4, 9, 4])\n', NP + 'a = np.array([4, 7, 4, 9, 4])\nprint(np.where(a == 4)[0])', "`np.where(condition)` gives a tuple with one array of positions per dimension. `[0]` takes the positions."),
 W(1, UFUNC, '`a = np.array([10, 20, 30])` and `b = np.array([3, 4, 5])`. Print `np.add(a, b)` and `np.mod(a, b)` with one `print()`.', NP + 'a = np.array([10, 20, 30])\nb = np.array([3, 4, 5])\n', NP + 'a = np.array([10, 20, 30])\nb = np.array([3, 4, 5])\nprint(np.add(a, b), np.mod(a, b))', "ufuncs work value by value, like `+` and `%` on arrays."),
 W(1, UFUNC, '`sales = np.array([120, 80, 150])`. Print the running total with `np.cumsum`.', NP + 'sales = np.array([120, 80, 150])\n', NP + 'sales = np.array([120, 80, 150])\nprint(np.cumsum(sales))', "`cumsum` adds up as it goes: each value is the total so far."),
 F(1, SPLIT, "This code should split 7 numbers into 3 parts (3, 2 and 2 values), but it crashes. Fix it.", NP + 'for part in np.split(np.arange(7), 3):\n    print(part)', NP + 'for part in np.array_split(np.arange(7), 3):\n    print(part)', "`np.split` needs parts of exactly equal size. `np.array_split` allows unequal parts."),
 T(1, UFUNC, NP + 'print(np.around([0.5, 1.5, 2.5, 3.5]))', "NumPy rounds halves to the nearest even number, like Python's `round()`: 0, 2, 2, 4."),
 F(1, SEARCH, "This code should print how many 3s there are: `2`. Fix it.", NP + 'a = np.array([3, 8, 3])\nprint(len(np.where(a == 3)))', NP + 'a = np.array([3, 8, 3])\nprint(len(np.where(a == 3)[0]))', "`np.where` returns a tuple (one item per dimension), so its length is 1. Count the positions inside it with `[0]`."),
 # ---------- Medium ----------
 W(2, LOOP, '`m = np.array([[10, 20], [30, 40]])`. Print each position and its value with `np.ndenumerate`, one per line.', NP + 'm = np.array([[10, 20], [30, 40]])\n', NP + 'm = np.array([[10, 20], [30, 40]])\nfor pos, value in np.ndenumerate(m):\n    print(pos, value)', "`ndenumerate` is `enumerate` for arrays: it gives the (row, column) position with each value."),
 W(2, SEARCH, 'Price slabs start at `slabs = np.array([100, 250, 400, 900])`. For the new prices `[50, 300, 1000]`, print the positions where they would be inserted to keep the order, using `np.searchsorted`.', NP + 'slabs = np.array([100, 250, 400, 900])\n', NP + 'slabs = np.array([100, 250, 400, 900])\nprint(np.searchsorted(slabs, [50, 300, 1000]))', "`searchsorted` finds where each value fits in a sorted array: before 100, between 250 and 400, and after 900."),
 T(2, RAND, NP + 'np.random.seed(42)\nrolls = np.random.randint(1, 7, size=500)\nprint(rolls.min(), rolls.max(), len(rolls))', "`randint(1, 7)` gives 1 to 6 (7 is not included). With 500 rolls, both 1 and 6 surely appear."),
 W(2, RAND, '`a = np.array([1, 2, 3, 4, 5])`. Make a shuffled copy with `np.random.permutation`. Print whether the sorted copy equals `a` (use `np.array_equal`), then print `a` itself.', NP + 'a = np.array([1, 2, 3, 4, 5])\n', NP + 'a = np.array([1, 2, 3, 4, 5])\np = np.random.permutation(a)\nprint(np.array_equal(np.sort(p), a))\nprint(a)', "`permutation` returns a new shuffled array and leaves `a` alone. Checking the sorted copy avoids printing random values."),
 W(2, UFUNC, '`readings = np.array([100, 120, 90, 130])`. Print the day-to-day changes with `np.diff`, then the biggest rise.', NP + 'readings = np.array([100, 120, 90, 130])\n', NP + 'readings = np.array([100, 120, 90, 130])\nchanges = np.diff(readings)\nprint(changes)\nprint(changes.max())', "`np.diff` subtracts each value from the next one, so the result has one value fewer."),
 F(2, UFUNC, "This code should print the greatest common divisor of 12 and 18, `6`. Fix it.", NP + 'print(np.lcm(12, 18))', NP + 'print(np.gcd(12, 18))', "`lcm` is the lowest common multiple (36). The greatest common divisor is `gcd`."),
 T(2, SPLIT, NP + 'print([len(p) for p in np.array_split(np.arange(11), 4)])', "11 values into 4 parts: the first parts get one extra value each, so 3, 3, 3 and 2."),
 W(2, DIST, 'After `np.random.seed(3)`, make 100000 values from a normal distribution with mean 500 and standard deviation 50. Print the mean and the standard deviation, both rounded to whole numbers.', NP + 'np.random.seed(3)\n', NP + 'np.random.seed(3)\nvalues = np.random.normal(loc=500, scale=50, size=100000)\nprint(round(values.mean()), round(values.std()))', "With many values, the sample mean and spread come very close to the settings, so the rounded results are stable."),
 W(2, UFUNC, '`a = np.array([1, 2, 3, 4])` and `b = np.array([3, 4, 5])`. Print the values in both, the values only in `a`, and all values, using `np.intersect1d`, `np.setdiff1d` and `np.union1d`.', NP + 'a = np.array([1, 2, 3, 4])\nb = np.array([3, 4, 5])\n', NP + 'a = np.array([1, 2, 3, 4])\nb = np.array([3, 4, 5])\nprint(np.intersect1d(a, b), np.setdiff1d(a, b), np.union1d(a, b))', "These are set operations for arrays, and the results come back sorted."),
 F(2, LOOP, "This code should print every value on one line: `1 2 3 4`. Fix the loop.", NP + 'm = np.array([[1, 2], [3, 4]])\nfor x in m:\n    print(x, end=" ")', NP + 'm = np.array([[1, 2], [3, 4]])\nfor x in np.nditer(m):\n    print(x, end=" ")', "A plain loop over a 2D array gives rows. `np.nditer` visits every single value."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, SPLIT, '`days = np.arange(1, 15) * 100` holds 14 days of sales. Split it into 2 weeks with `np.split`, and print a list of the two weekly totals as plain ints.', NP + 'days = np.arange(1, 15) * 100\n', NP + 'days = np.arange(1, 15) * 100\nprint([int(week.sum()) for week in np.split(days, 2)])', "Split first, then summarise each part. `int()` turns NumPy numbers into plain Python ints for a clean list."),
 W(3, DIST, 'After `np.random.seed(3)`, simulate 100000 days of bookings with `np.random.binomial(n=20, p=0.25, size=100000)`. Print the mean rounded to a whole number, whether every value is 0 or more, and whether every value is 20 or less.', NP + 'np.random.seed(3)\n', NP + 'np.random.seed(3)\nbookings = np.random.binomial(n=20, p=0.25, size=100000)\nprint(round(bookings.mean()), bookings.min() >= 0, bookings.max() <= 20)', "A binomial count is between 0 and n, and its mean is n × p = 5. Check properties, not exact random values."),
 W(3, SEARCH, '`rates = np.array([1200, 3400, 1200, 5600, 3400])`. Print the positions of the rate 3400, then how many rates are below 2000.', NP + 'rates = np.array([1200, 3400, 1200, 5600, 3400])\n', NP + 'rates = np.array([1200, 3400, 1200, 5600, 3400])\nprint(np.where(rates == 3400)[0])\nprint(len(rates[rates < 2000]))', "`np.where` finds positions; a mask finds the matching values, and `len()` counts them."),
 T(3, UFUNC, NP + 'print(np.floor([-1.5, 2.7]), np.ceil([-1.5, 2.7]), np.trunc([-1.5, 2.7]))', "`floor` always goes down, `ceil` always goes up, and `trunc` just cuts off the decimals (towards 0)."),
 W(3, RAND, 'After `np.random.seed(1)`, pick 10000 days with `np.random.choice(["late", "on time"], p=[0.2, 0.8], size=10000)`. Print the share of on-time days, rounded to 1 decimal.', NP + 'np.random.seed(1)\n', NP + 'np.random.seed(1)\ndays = np.random.choice(["late", "on time"], p=[0.2, 0.8], size=10000)\nprint(round(np.mean(days == "on time"), 1))', "`days == \"on time\"` is an array of True/False, and its mean is the share of True values: about 0.8."),
 F(3, SEARCH, "`np.searchsorted` should say where 300 fits among these prices in sorted order: `2`. Fix it.", NP + 'prices = np.array([100, 900, 250, 400])\nprint(np.searchsorted(prices, 300))', NP + 'prices = np.array([100, 900, 250, 400])\nprint(np.searchsorted(np.sort(prices), 300))', "`searchsorted` only works on a sorted array. Sort the prices first."),
 W(3, UFUNC, 'Write a function `slab(amount)` that returns `"High"` for 1000 or more and `"Low"` otherwise. Turn it into a ufunc with `np.frompyfunc(slab, 1, 1)` and print the result for `np.array([500, 1500, 1000])`.', NP + '# def slab(amount):\n', NP + 'def slab(amount):\n    return "High" if amount >= 1000 else "Low"\n\nslab_u = np.frompyfunc(slab, 1, 1)\nprint(slab_u(np.array([500, 1500, 1000])))', "`frompyfunc` wraps your own Python function so it runs on every value of an array."),
]
